    {
        $graph = (new ExperimentAnalyzer())->analyze(dirname(__DIR__, 3).'/Fixture/Sample/ComplexSample.php');

        self::assertNotNull($graph->nodeNamed('Tests\Fixture\Sample\ComplexClass'));
    }
